<section class="page-heading">
    <div><div class="eyebrow">Reference data</div><h1>Commodities</h1><p>Define active commodities, units, and the acceptable price range used by server validation.</p></div>
    <div class="heading-actions"><button class="button button-primary" type="button" data-open-modal="commodity-modal"><i class="fa-solid fa-plus"></i><span>Add commodity</span></button></div>
</section>
<section class="panel"><div class="table-wrap"><table class="data-table"><caption class="visually-hidden">Commodities with images, units, allowed price ranges, and status</caption><thead><tr><th scope="col">Commodity</th><th scope="col">Category</th><th scope="col">Unit</th><th scope="col">Allowed range</th><th scope="col">Status</th><th scope="col">Photo</th><th scope="col">Actions</th></tr></thead><tbody id="commodities-table"><tr><td colspan="7" class="table-loading"><i class="fa-solid fa-circle-notch fa-spin"></i><span>Loading commodities</span></td></tr></tbody></table></div></section>
<div class="modal" id="commodity-modal" role="dialog" aria-modal="true" aria-labelledby="commodity-title"><div class="modal-dialog"><div class="modal-header"><h2 id="commodity-title">Add commodity</h2><button class="icon-button" type="button" data-modal-close aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><form id="commodity-form"><div class="modal-body"><div class="form-grid"><div class="form-field form-field-full"><label for="commodity-name">Name <span>*</span></label><input id="commodity-name" name="name" required><span class="field-error" data-error-for="name"></span></div><div class="form-field form-field-full"><label for="commodity-image-input">Product photo</label><input id="commodity-image-input" type="file" accept="image/jpeg,image/png,image/webp" hidden><input id="image-current-path" type="hidden"><div class="image-dropzone" id="commodity-image-preview" role="button" tabindex="0" aria-label="Upload a product photo"></div><span class="form-hint">Shown beside prices on the public dashboard, USSD, and SMS alerts.</span><button class="button button-small button-danger" type="button" id="commodity-image-remove" hidden><i class="fa-solid fa-trash-can"></i><span>Remove photo</span></button></div><div class="form-field"><label for="commodity-unit">Unit <span>*</span></label><input id="commodity-unit" name="unit_of_measure" placeholder="KG" required><span class="field-error" data-error-for="unit_of_measure"></span></div><div class="form-field"><label for="commodity-category">Category <span>*</span></label><select id="commodity-category" name="category" required><option value="cereal">Cereal</option><option value="legume">Legume</option><option value="vegetable">Vegetable</option><option value="livestock">Livestock</option></select><span class="field-error" data-error-for="category"></span></div><div class="form-field"><label for="commodity-active">Availability</label><select id="commodity-active" name="is_active"><option value="1">Active</option><option value="0">Inactive</option></select></div><div class="form-field"><label for="commodity-min">Minimum price <span>*</span></label><input id="commodity-min" name="min_price" type="number" min="0.01" step="0.01" required><span class="field-error" data-error-for="min_price"></span></div><div class="form-field"><label for="commodity-max">Maximum price <span>*</span></label><input id="commodity-max" name="max_price" type="number" min="0.01" step="0.01" required><span class="field-error" data-error-for="max_price"></span></div></div></div><div class="modal-footer"><button class="button button-secondary" type="button" data-modal-close>Cancel</button><button class="button button-primary" type="submit"><i class="fa-solid fa-check"></i><span>Save commodity</span></button></div></form></div></div>
